// Executor rehearsal only: decisions are scripted, not generated by a model.
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const http = require('node:http');
const path = require('node:path');
const { chromium } = require('playwright');

(async () => {
  const output = path.resolve(process.env.OUTPUT_DIR || path.join(__dirname, 'output'));
  await fs.mkdir(output, { recursive: true });
  const fixture = await fs.readFile(path.join(__dirname, 'index.html'));
  const server = http.createServer((req, res) => {
    if (req.url !== '/') { res.writeHead(404).end(); return; }
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(fixture);
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  let browser;
  try {
    browser = await chromium.launch({
      ...(process.env.CHROMIUM_PATH ? { executablePath: process.env.CHROMIUM_PATH } : {}),
    });
    const context = await browser.newContext({ viewport: { width: 1200, height: 675 }, deviceScaleFactor: 1 });
    const page = await context.newPage();
    await page.goto(`http://127.0.0.1:${server.address().port}/`);
    const status = () => page.locator('#status').getAttribute('data-state');
    const evidence = async (title, events) => {
      const snapshot = await page.locator('#workspace').ariaSnapshot();
      await page.locator('#phase').evaluate((el, text) => { el.textContent = text; }, title);
      await page.locator('#snapshot').evaluate((el, text) => { el.textContent = text; }, snapshot);
      await page.locator('#events').evaluate((el, items) => {
        el.replaceChildren(...items.map(text => {
          const li = document.createElement('li'); li.textContent = text; return li;
        }));
      }, events);
      return snapshot;
    };
    const before = await evidence('Actual accessibility snapshot', ['Read the page before choosing a target.']);
    assert.match(before, /button "Confirm review"/);
    await fs.writeFile(path.join(output, 'before.aria.txt'), before + '\n');
    await page.screenshot({ path: path.join(output, '01-observation.png') });

    const button = page.getByRole('button', { name: 'Confirm review', exact: true });
    const box = await button.boundingBox();
    assert.ok(box);
    const oldPoint = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
    await page.getByRole('button', { name: 'Expand diagnostics', exact: true }).click();
    const moved = await button.boundingBox();
    assert.ok(moved && moved.y > box.y + box.height);
    await page.mouse.click(oldPoint.x, oldPoint.y);
    assert.equal(await status(), 'pending');
    await evidence('Old coordinates after a layout change', [
      `Old click: (${oldPoint.x.toFixed(1)}, ${oldPoint.y.toFixed(1)}) CSS px.`,
      'The button moved; the old click did not complete the review.',
      'Verified result: status is still pending.',
    ]);
    await page.screenshot({ path: path.join(output, '02-stale-coordinate.png') });

    await button.click();
    assert.equal(await status(), 'done');
    await page.reload();
    assert.equal(await status(), 'done');
    const after = await evidence('Fresh locator and independent verification', [
      'Resolved the current button with getByRole().',
      'Clicked once; read the resulting state.',
      'Reloaded the page; the saved result remains present.',
    ]);
    await fs.writeFile(path.join(output, 'after.aria.txt'), after + '\n');
    await page.screenshot({ path: path.join(output, '03-verified-result.png') });
    const result = {
      kind: 'scripted-executor-rehearsal', modelInference: false,
      mcpProtocolTested: false, desktopControlTested: false,
      playwright: require('playwright/package.json').version,
      viewport: { width: 1200, height: 675 }, coordinateUnit: 'CSS pixels',
      oldPoint, buttonBefore: box, buttonAfter: moved,
      staleCoordinateResult: 'pending', freshLocatorResult: 'done', afterReload: 'done',
    };
    await fs.writeFile(path.join(output, 'result.json'), JSON.stringify(result, null, 2) + '\n');
    console.log(JSON.stringify(result, null, 2));
  } finally {
    if (browser) await browser.close();
    await new Promise(resolve => server.close(resolve));
  }
})().catch(error => { console.error(error); process.exitCode = 1; });
